)

delete from PBC_REPORT_GENERAT_CHECKDETAIL
 where CHECK_UUID IN (
select prgc.DATA_UUID from PBC_REPORT_GENERATION_CHECK prgc
where prgc.REPORT_NAME = #{tableName,jdbcType=VARCHAR}

    #{item,jdbcType=VARCHAR}

)

delete from PBC_REPORT_GENERAT_CHECKDETAIL
where CHECK_UUID IN (
select prgc.DATA_UUID from PBC_REPORT_GENERATION_CHECK prgc
where prgc.REPORT_NAME = #{tableName,jdbcType=VARCHAR}
and  prgc.IN_FLAG='02'
)

delete from pbc_report_generation_check
where  REPORT_NAME = #{tableName,jdbcType=VARCHAR}
and IN_FLAG='02'

mapper.select:
SELECT t1.DATA_UUID AS dataUuid, t1.DATA_ID AS dataId, t3.RULE_ID AS ruleId, t3.PBC_ASSET_CODE AS pbcElementCode, t3.TABLE_DATA_NAME AS reportName, t3.CHECKED_FIELD_NAME AS fieldName, t3.RULE_TYPE AS ruleType, t3.RULE_IDENTIFY AS ruleCode, t3.RULE_CONTENT AS ruleDetails, t1.ORG_DATA AS orgData, t1.CHECK_DATE AS checkDate, t2.CHECK_RESULT AS checkResult, t2.CHECK_FLAG AS checkFlag FROM pbc_report_generation_check t1 LEFT JOIN pbc_report_generat_checkdetail t2 ON t1.DATA_UUID = t2.CHECK_UUID LEFT JOIN pbc_check_rule_info t3 ON t3.RULE_ID = t2.RULE_ID where 1=1 and t1.IN_FLAG='02' AND CHECK_FLAG='1' and t1.REPORT_NAME in( SELECT tri.TABLE_DATA_NAME FROM pbc_check_rule_info tri where 1=1
and tri.rule_id = #{ruleId,jdbcType=VARCHAR}
) order by cast(t1.DATA_ID as unsigned integer )
